### Startup Configuration

```csharp
public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Database
        services.AddDbContext<DataContext>(opt =>
        {
            opt.UseSqlServer(Configuration.GetConnectionString("DefaultConnection"));
        });

        // MediatR for CQRS
        services.AddMediatR(typeof(List.Handler).Assembly);

        // AutoMapper
        services.AddAutoMapper(typeof(List.Handler));

        // SignalR
        services.AddSignalR().AddAzureSignalR();

        // Redis cache
        services.AddStackExchangeRedisCache(options =>
        {
            options.Configuration = Configuration.GetConnectionString("Redis");
        });

        // Authentication
        services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
            .AddJwtBearer(opt =>
            {
                opt.TokenValidationParameters = new TokenValidationParameters
                {
                    ValidateIssuerSigningKey = true,
                    IssuerSigningKey = new SymmetricSecurityKey(
                        Encoding.UTF8.GetBytes(Configuration["TokenKey"])
                    ),
                    ValidateIssuer = false,
                    ValidateAudience = false
                };

                // SignalR JWT
                opt.Events = new JwtBearerEvents
                {
                    OnMessageReceived = context =>
                    {
                        var accessToken = context.Request.Query["access_token"];
                        var path = context.HttpContext.Request.Path;

                        if (!string.IsNullOrEmpty(accessToken) && 
                            path.StartsWithSegments("/chat"))
                        {
                            context.Token = accessToken;
                        }

                        return Task.CompletedTask;
                    }
                };
            });
    }
}
```

### Redux-Saga for Async Operations

```typescript
// Event sagas
function* fetchEvents() {
  try {
    yield put({ type: 'FETCH_EVENTS_REQUEST' });

    const events: Event[] = yield call(api.events.list);

    yield put({
      type: 'FETCH_EVENTS_SUCCESS',
      payload: events
    });
  } catch (error) {
    yield put({
      type: 'FETCH_EVENTS_FAILURE',
      payload: error.message
    });
  }
}

function* createEvent(action) {
  try {
    yield put({ type: 'CREATE_EVENT_REQUEST' });

    const event: Event = yield call(api.events.create, action.payload);

    yield put({
      type: 'CREATE_EVENT_SUCCESS',
      payload: event
    });

    // Navigate to new event
    yield call(history.push, `/events/${event.id}`);
  } catch (error) {
    yield put({
      type: 'CREATE_EVENT_FAILURE',
      payload: error.message
    });
  }
}

export function* eventsSaga() {
  yield takeEvery('FETCH_EVENTS', fetchEvents);
  yield takeLatest('CREATE_EVENT', createEvent);
}
```

