### Memory Management

```rust
// Efficient pixel buffer handling
use wasm_bindgen::Clamped;

#[wasm_bindgen]
pub fn process_large_image(pixels: Clamped<Vec<u8>>) -> Clamped<Vec<u8>> {
    let mut output = Vec::with_capacity(pixels.len());

    // Process without intermediate allocations
    for chunk in pixels.chunks_exact(4) {
        let gray = (0.299 * chunk[0] as f32 + 
                   0.587 * chunk[1] as f32 + 
                   0.114 * chunk[2] as f32) as u8;

        output.extend_from_slice(&[gray, gray, gray, chunk[3]]);
    }

    Clamped(output)
}
```

### Performance Optimization

**Parallel Processing:**
```rust
use rayon::prelude::*;

pub fn parallel_grayscale(pixels: &[u8]) -> Vec<u8> {
    pixels
        .par_chunks(4)  // Parallel iteration
        .flat_map(|chunk| {
            let gray = luminosity_method(chunk);
            vec![gray, gray, gray, chunk[3]]
        })
        .collect()
}
```

**SIMD Acceleration:**
```rust
#[cfg(target_arch = "wasm32")]
use std::arch::wasm32::*;

pub fn simd_grayscale(pixels: &[u8]) -> Vec<u8> {
    // Process 16 bytes at once with SIMD
    unsafe {
        let mut output = Vec::with_capacity(pixels.len());

        for chunk in pixels.chunks_exact(16) {
            let vec = v128_load(chunk.as_ptr() as *const v128);
            // SIMD operations for grayscale conversion
            let processed = process_simd(vec);
            output.extend_from_slice(&v128_to_bytes(processed));
        }

        output
    }
}
```

