### Shared State Management

```typescript
// Event-based communication between micro-frontends
class MicroFrontendBus {
  private listeners: Map<string, Set<Function>> = new Map();

  subscribe(event: string, callback: Function) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(callback);

    // Return unsubscribe function
    return () => {
      this.listeners.get(event)?.delete(callback);
    };
  }

  publish(event: string, data: any) {
    const callbacks = this.listeners.get(event);
    if (callbacks) {
      callbacks.forEach(callback => callback(data));
    }
  }
}

// Global instance
window.mfeBus = window.mfeBus || new MicroFrontendBus();

// Usage in React app
function ReactComponent() {
  useEffect(() => {
    const unsubscribe = window.mfeBus.subscribe('user.login', (user) => {
      setCurrentUser(user);
    });

    return unsubscribe;
  }, []);

  const handleLogin = (user) => {
    window.mfeBus.publish('user.login', user);
  };
}
