## Technical Implementation

### Router Implementation

```php
<?php
namespace Galaxy\Core;

class Router {
    private $routes = [];
    private $namedRoutes = [];

    public function get($uri, $controller, $action, $name = null) {
        $this->addRoute('GET', $uri, $controller, $action, $name);
    }

    public function post($uri, $controller, $action, $name = null) {
        $this->addRoute('POST', $uri, $controller, $action, $name);
    }

    private function addRoute($method, $uri, $controller, $action, $name) {
        // Convert route parameters to regex
        $pattern = preg_replace('/\{([a-zA-Z0-9_]+)\}/', '(?P<$1>[^/]+)', $uri);
        $pattern = '#^' . $pattern . '$#';

        $route = [
            'method' => $method,
            'pattern' => $pattern,
            'controller' => $controller,
            'action' => $action,
            'uri' => $uri
        ];

        $this->routes[] = $route;

        if ($name) {
            $this->namedRoutes[$name] = $route;
        }
    }

    public function dispatch($uri, $method) {
        foreach ($this->routes as $route) {
            if ($route['method'] !== $method) {
                continue;
            }

            if (preg_match($route['pattern'], $uri, $matches)) {
                // Extract parameters
                $params = array_filter($matches, 'is_string', ARRAY_FILTER_USE_KEY);

                // Instantiate controller
                $controllerClass = $route['controller'];
                $controller = new $controllerClass();

                // Call action with parameters
                return call_user_func_array(
                    [$controller, $route['action']],
                    $params
                );
            }
        }

        throw new \Exception('Route not found', 404);
    }
}
```

### Database Abstraction Layer

```php
<?php
namespace Galaxy\Database;

class Database {
    private $pdo;
    private $statement;

    public function __construct($config) {
        $dsn = "mysql:host={$config['host']};dbname={$config['database']}";

        $this->pdo = new \PDO($dsn, $config['username'], $config['password'], [
            \PDO::ATTR_ERRMODE => \PDO::ERRMODE_EXCEPTION,
            \PDO::ATTR_DEFAULT_FETCH_MODE => \PDO::FETCH_ASSOC,
            \PDO::ATTR_EMULATE_PREPARES => false
        ]);
    }

    public function query($sql, $params = []) {
        $this->statement = $this->pdo->prepare($sql);
        $this->statement->execute($params);
        return $this;
    }

    public function fetchAll() {
        return $this->statement->fetchAll();
    }

    public function fetch() {
        return $this->statement->fetch();
    }

    // Query builder methods
    public function table($table) {
        return new QueryBuilder($this->pdo, $table);
    }
}

class QueryBuilder {
    private $pdo;
    private $table;
    private $wheres = [];
    private $params = [];

    public function __construct($pdo, $table) {
        $this->pdo = $pdo;
        $this->table = $table;
    }

    public function where($column, $operator, $value) {
        $this->wheres[] = "$column $operator ?";
        $this->params[] = $value;
        return $this;
    }

    public function get() {
        $sql = "SELECT * FROM {$this->table}";

        if (!empty($this->wheres)) {
            $sql .= " WHERE " . implode(' AND ', $this->wheres);
        }

        $stmt = $this->pdo->prepare($sql);
        $stmt->execute($this->params);

        return $stmt->fetchAll();
    }

    public function first() {
        $results = $this->get();
        return $results[0] ?? null;
    }
}
```

### Base Model Class

```php
<?php
namespace Galaxy\Core;

abstract class Model {
    protected $db;
    protected $table;
    protected $primaryKey = 'id';

    public function __construct() {
        $this->db = App::get('database');
    }

    public function find($id) {
        return $this->db
            ->table($this->table)
            ->where($this->primaryKey, '=', $id)
            ->first();
    }

    public function all() {
        return $this->db
            ->table($this->table)
            ->get();
    }

    public function save($attributes) {
        $columns = implode(', ', array_keys($attributes));
        $placeholders = implode(', ', array_fill(0, count($attributes), '?'));

        $sql = "INSERT INTO {$this->table} ($columns) VALUES ($placeholders)";

        return $this->db->query($sql, array_values($attributes));
    }

    public function update($id, $attributes) {
        $set = implode(', ', array_map(function($key) {
            return "$key = ?";
        }, array_keys($attributes)));

        $sql = "UPDATE {$this->table} SET $set WHERE {$this->primaryKey} = ?";
        $params = array_merge(array_values($attributes), [$id]);

        return $this->db->query($sql, $params);
    }
}
```

### PSR-4 Autoloader

```php
<?php
// Autoloader implementation
spl_autoload_register(function ($class) {
    // Project-specific namespace prefix
    $prefix = 'Galaxy\\';

    // Base directory for the namespace prefix
    $baseDir = __DIR__ . '/app/';

    // Check if class uses the namespace prefix
    $len = strlen($prefix);
    if (strncmp($prefix, $class, $len) !== 0) {
        return;
    }

    // Get relative class name
    $relativeClass = substr($class, $len);

    // Replace namespace separators with directory separators
    $file = $baseDir . str_replace('\\', '/', $relativeClass) . '.php';

    // If file exists, require it
    if (file_exists($file)) {
        require $file;
    }
});
```

