```typescript
// Octo's federation configuration generator
interface OctoConfig {
  name: string;
  framework: 'react' | 'vue' | 'svelte' | 'preact';
  exposes?: Record<string, string>;
  remotes?: Record<string, string>;
  shared?: Record<string, any>;
}

function generateFederationConfig(config: OctoConfig) {
  const baseShared = getFrameworkShared(config.framework);

  return {
    name: config.name,
    filename: 'remoteEntry.js',
    exposes: config.exposes || {},
    remotes: Object.entries(config.remotes || {}).reduce(
      (acc, [key, value]) => {
        acc[key] = `${key}@${value}/remoteEntry.js`;
        return acc;
      },
      {}
    ),
    shared: {
      ...baseShared,
      ...config.shared
    }
  };
}

function getFrameworkShared(framework: string) {
  const sharedConfigs = {
    react: {
      react: { singleton: true, requiredVersion: '^18.0.0' },
      'react-dom': { singleton: true, requiredVersion: '^18.0.0' }
    },
