### DataLoader for N+1 Prevention

```typescript
import DataLoader from 'dataloader';

class LoanDataSource {
  private db: Database;
  private borrowerLoader: DataLoader<string, Borrower>;

  constructor(db: Database) {
    this.db = db;

    // Batch load borrowers
    this.borrowerLoader = new DataLoader<string, Borrower>(
      async (borrowerIds) => {
        const borrowers = await this.db.query(
          'SELECT * FROM Borrowers WHERE Id IN (?)',
          [borrowerIds]
        );

        // Return in same order as requested
        const borrowerMap = new Map(
          borrowers.map(b => [b.id, b])
        );

        return borrowerIds.map(id => borrowerMap.get(id));
      },
      {
        cache: true,
        batchScheduleFn: (callback) => setTimeout(callback, 10)
      }
    );
  }

  async getLoanBorrower(loanId: string): Promise<Borrower> {
    const loan = await this.db.findLoan(loanId);
    return this.borrowerLoader.load(loan.borrowerId);
  }
}
