// Framework-agnostic component wrapper
const OctoComponent = ({ framework, component, props }) => {
  const containerRef = useRef();

  useEffect(() => {
    if (framework === 'react') {
      ReactDOM.render(<Component {...props} />, containerRef.current);
    } else if (framework === 'vue') {
      new Vue({ render: h => h(component, { props }) })
        .$mount(containerRef.current);
    }

    return () => cleanup(framework, containerRef.current);
  }, [framework, component, props]);

  return <div ref={containerRef} />;
};
